#include <stdint.h>
#include "stm32f4xx.h"

void init_gpio();

void init_tim3();

int main(void)
{
    //Llamar a las funciones de configuracion
    init_gpio();

    //Llamar a la funcion de configuracion del timer 3, interrupcion cada 0.25s
    init_tim3();

    /* Loop forever */
    while(1){
    }
    return 0;
}

void init_gpio(){
    RCC->AHB1ENR &= ~(1 << 0);
    RCC->AHB1ENR &=RCC_AHB1ENR_GPIOAEN; //LIMPIANDO LA POSICION
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN; //ACTIVANDO LA SEÑAL
    // Configurando el pin A5
    GPIOA->MODER &= ~(0b11 << GPIO_MODER_MODE5_Pos); // Limpiando la posición
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODE5_Pos); // Configurando como salida

    GPIOA ->OTYPER &= ~(GPIO_OTYPER_OT5); // Limpiando la posicion -Configurando como push-pull

    GPIOA ->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED5_Pos); // Limpiando la posición
    GPIOA ->OSPEEDR |= (0b10 << GPIO_OSPEEDR_OSPEED5_Pos); // Velocidad media

    GPIOA ->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD5_Pos); // Limpiando Y desactivando el pull-up/pull-down

    GPIOA->ODR |= (GPIO_ODR_OD5); // Encenger el pin A5
}


void init_tim3(){
    RCC->APB1ENR &= ~RCC_APB1ENR_TIM3EN; // Limpiando la posición
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN; //Activar la señal del reloj para el TIM3


    TIM3->CNT = 0; // Inicializando el contador en 0
    TIM3->PSC = (1600-1); // divisor por 1600, para que el reloj del timer sea de 10kHz
    TIM3->ARR = (2500-1); // para generar un evento update cada 250ms (10kHz / 2500 = 4Hz)

    TIM3->CR1 &= ~(0X3 <<TIM_CR1_CKD_Pos); // Limpiamos, dejar la señal de reloj completa
    TIM3->CR1 &= ~(TIM_CR1_ARPE); //Limpiamos la posicion
    TIM3->CR1 |= (TIM_CR1_ARPE); // Activamos la precarga del registro ARR
    TIM3->CR1 &= ~TIM_CR1_DIR; // Contador ascendente 

    TIM3->DIER |= TIM_DIER_UIE; // Habilitamos la interrupcion debido a un update event

    //Activamos la interrupcion TIM3 en el NVIC
    NVIC_EnableIRQ(TIM3_IRQn);

    TIM3->CR1 |= TIM_CR1_CEN; // Activamos el contador
}
 
/*Rutina de atencion a la interrupcion del TIM3
* El nombre de esta  funcion se toma del vector de interrupciones definido
* en el archivo startup_stm32f411xe.s (no modificar este archivo)
*/
void TIM3_IRQHandler(void){
    //VERIFICAMOS SI LA BANDERA ESTA LEVANTADA
    if(TIM3->SR && TIM_SR_UIF){
        TIM3->SR &= ~TIM_SR_UIF; // Limpiando la bandera


        GPIOA->ODR ^= GPIO_ODR_OD5; // 
    }

}

